INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7436170, 1175470, 104230, '<td valign="top">This has to be a West County lane -- the style of signage is certainly British. It reminds me of single track roads in Devon. After hundreds of years of use most were at a considerably lower level than the surrounding fields, and after a heavy rain would be covered with mud left by tractors or that had run off from the fields.<br/> <br/>Perhaps this is the aftermath of storm Imogen?</td>', 'This has to be a West County lane -- the style of signage is certainly British. It reminds me of single track roads in Devon. After hundreds of years of use most were at a considerably lower level than the surrounding fields, and after a heavy rain would be covered with mud left by tractors or that had run off from the fields. Perhaps this is the aftermath of storm Imogen?', '2016-02-10 00:46:12.000000', NULL, 1),
(7436182, 1175712, 113078, '<td valign="top">I love the look of this</td>', 'I love the look of this', '2016-02-10 01:12:01.000000', NULL, 1),
(7436183, 1175489, 113078, '<td valign="top">Meets the challenge</td>', 'Meets the challenge', '2016-02-10 01:12:51.000000', NULL, 1),
