(7436194, 1175415, 114285, '<td valign="top">One word! <br/> <br/> <br/>LOL!!</td>', 'One word!   LOL!!', '2016-02-10 03:39:47.000000', NULL, 1),
(7436195, 1175678, 114285, '<td valign="top">Ha, that is brilliant! His body language even!!</td>', 'Ha, that is brilliant! His body language even!!', '2016-02-10 03:40:43.000000', NULL, 1),
(7436231, 1175446, 181814, '<td valign="top">A tighter crop and less noise would have worked better, as it is now the sign is the secondary subject.</td>', 'A tighter crop and less noise would have worked better, as it is now the sign is the secondary subject.', '2016-02-10 09:14:38.000000', NULL, 1),
(7436232, 1175468, 181814, '<td valign="top">It seems to be a bit underexposed and the composition of the sign is not that efective.</td>', 'It seems to be a bit underexposed and the composition of the sign is not that efective.', '2016-02-10 09:15:50.000000', NULL, 1),
(7436233, 1175519, 181814, '<td valign="top">Most of the photograph seems to be blown out by harsh lighting or over processing.</td>', 'Most of the photograph seems to be blown out by harsh lighting or over processing.', '2016-02-10 09:16:56.000000', NULL, 1),
(7436234, 1175720, 181814, '<td valign="top">I do get the point "three of them" but it is not a sign at all.</td>', 'I do get the point "three of them" but it is not a sign at all.', '2016-02-10 09:17:52.000000', NULL, 1),
(7436235, 1175425, 181814, '<td valign="top">The composition could be much better and the entire photograph is out of focus.</td>', 'The composition could be much better and the entire photograph is out of focus.', '2016-02-10 09:18:32.000000', NULL, 1),
(7436236, 1175742, 181814, '<td valign="top">The signs seem to be not of much importance, maybe a tighter crop would work better.</td>', 'The signs seem to be not of much importance, maybe a tighter crop would work better.', '2016-02-10 09:19:44.000000', NULL, 1),
(7436239, 1175558, 181814, '<td valign="top">I like the photograph in black and white, there are a few white spots on the sign that could have been edited out, BUTT overall nice find and photograph.</td>', 'I like the photograph in black and white, there are a few white spots on the sign that could have been edited out, BUTT overall nice find and photograph.', '2016-02-10 09:29:27.000000', NULL, 1),
(7436240, 1175678, 181814, '<td valign="top">I really like this, it is one of my favorites in the contest, it is a very unique find and I hope it does well, I am giving it a ten because it is by far the best entry in this contest in my opinion.</td>', 'I really like this, it is one of my favorites in the contest, it is a very unique find and I hope it does well, I am giving it a ten because it is by far the best entry in this contest in my opinion.', '2016-02-10 09:31:33.000000', NULL, 1),
(7436241, 1175743, 181814, '<td valign="top">Very fitting composition because it does look like everyone is on the GO, very well done.</td>', 'Very fitting composition because it does look like everyone is on the GO, very well done.', '2016-02-10 09:32:29.000000', NULL, 1),
(7436242, 1175398, 181814, '<td valign="top">Great looking photograph, I like the composition the focus and pretty much everything else about the photograph.</td>', 'Great looking photograph, I like the composition the focus and pretty much everything else about the photograph.', '2016-02-10 09:33:56.000000', NULL, 1),
(7436243, 1175489, 181814, '<td valign="top">The lighting is very harsh, and I know you are trying to make a point but there is no sign in this photograph.</td>', 'The lighting is very harsh, and I know you are trying to make a point but there is no sign in this photograph.', '2016-02-10 09:39:17.000000', NULL, 1),
(7436244, 1175699, 181814, '<td valign="top">Not a bad photograph but I see no sign and will score it accordingly.</td>', 'Not a bad photograph but I see no sign and will score it accordingly.', '2016-02-10 09:40:09.000000', NULL, 1),
(7436245, 1175426, 181814, '<td valign="top">The overall photograph is a bit under exposed and I would consider this a poster rather than a sign, maybe a tighter crop would help out a little u.e. the bottom part is a bit distracting.</td>', 'The overall photograph is a bit under exposed and I would consider this a poster rather than a sign, maybe a tighter crop would help out a little u.e. the bottom part is a bit distracting.', '2016-02-10 09:41:43.000000', NULL, 1),
